# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARIM, HAYVANCILIK VE SANAYİNİN COĞRAFİ ETMENLERLE İLİŞKİSİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Tarım ve İklim-Yer Şekli</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Çukurova, Bafra, Çarşamba,</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#14532d">Konya ve Gediz ovaları ➔ Yoğun</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#14532d">• Akdeniz: Kış ılıklığı ➔ Seracılık,</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#14532d">turunçgil, muz, zeytin, pamuk</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" fill="#14532d">• Karadeniz: Her mevsim yağış ➔</text>\n  <text x="125" y="190" text-anchor="middle" font-size="11" fill="#14532d">Çay ve fındık · İç bölgeler: Buğday</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">GAP sulamasıyla pamuk arttı!</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Hayvancılık ve Bitki Örtüsü</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#713f12">• Erzurum-Kars ve Doğu Karadeniz:</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#713f12">Yaz yağışı ve gür çayır ➔ Büyükbaş</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#713f12">• İç ve Güneydoğu Anadolu:</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11" fill="#713f12">Bozkır bitki örtüsü ➔ Küçükbaş (Koyun)</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11" fill="#713f12">• Toroslar (Maki): Kıl keçisi</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" fill="#713f12">• Menteşe, Hakkâri, Rize: Arıcılık</text>\n  <text x="350" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Dut ağacı (Bursa, Diyarbakır): İpek</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">3. Sanayi ve Ham Madde-Ulaşım</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Tarım ürünü ➔ Gıda/Dokuma sanayi</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">(Konya un, Adana pamuklu dokuma)</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• Orman ➔ Kağıt ve kereste (Batı Kar.)</text>\n  <text x="575" y="160" text-anchor="middle" font-size="11" fill="#1e3a8a">• Maden ➔ Zonguldak taş kömürü ve</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" fill="#1e3a8a">demir-çelik, Batman petrol rafinerisi</text>\n  <text x="575" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• İstanbul, Kocaeli, Bursa, İzmir:</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" fill="#334155">Ulaşım ve pazar sayesinde gelişmiş sanayi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ULAŞIM, TURİZM VE YERLEŞME FAALİYETLERİNİN DOĞAL ÇEVREYLE İLİŞKİSİ</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Ulaşım ve Yeryüzü Şekilleri</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" fill="#155e75">• Dağlarımız doğu-batı uzanışlı olduğu için</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">doğu-batı yönlü ulaşım daha kolaydır.</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" fill="#155e75">• Kuzey ve güneyde kıyı ile iç kesim arasında</text>\n  <text x="180" y="158" text-anchor="middle" font-size="11" fill="#155e75">geçit ve tüneller kullanılır: Zigana, Ovit,</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" fill="#155e75">Ilgaz tünelleri; Gülek, Çubuk, Sertavul geçitleri.</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">• Boğaz köprüleri, Avrasya ve Marmaray</text>\n  <text x="180" y="218" text-anchor="middle" font-size="10.5" fill="#475569">beşerî teknolojinin doğal engeli aşmasıdır.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Turizm ve Konut Tipleri</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" fill="#581c87">• Güneşli kıyı (Antalya, Muğla) ➔ Yaz turizmi</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#581c87">• Yüksek dağ ve kar (Uludağ, Palandöken, Erciyes)</text>\n  <text x="520" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">➔ Kış ve kayak turizmi · Karadeniz ➔ Yayla</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#581c87">• Kırsal Konut Malzemesi (Doğal Çevre Etkisi):</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#581c87">Karadeniz (Orman) ➔ Ahşap ev · İç Anadolu ➔</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" fill="#581c87">Kerpiç ev · Akdeniz ve Kapadokya ➔ Taş ev</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">• Karadeniz: Dağınık · İç Anadolu: Toplu yerleşme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÖĞRENME ALANI DEĞERLENDİRMESİ: EVİMİZ DÜNYA (SB.6.2)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">1. Coğrafi Konum (SB.6.2.1)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#881337">• Mutlak Konum: 36°-42° Kuzey</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#881337">paralelleri, 26°-45° Doğu meridyenleri</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#881337">• Göreceli Konum: Asya, Avrupa</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#881337">ve Afrika\'nın kesişim noktası; boğazlar,</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" fill="#881337">yükselti ve üç tarafının deniz olması</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Kıtalar arası enerji ve ticaret köprüsü</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. İklim ve Doğal Çevre</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#7c2d12">• Akdeniz İklimi (Maki - Yaz kurak)</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#7c2d12">• Karadeniz İklimi (Orman - Her mevsim</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#7c2d12">yağışlı, nemli ve ılıman)</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#7c2d12">• Karasal İklim (Bozkır/Çayır - Kışları</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#7c2d12">soğuk ve karlı, yazları sıcak)</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Batıdan doğuya yükselti artar.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Sürdürülebilir Etkileşim</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Tarım arazileri ve ovalar sanayi</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#14532d">veya konut alanına açılmamalıdır.</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#14532d">• Yenilenebilir enerji (güneş, rüzgâr,</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#14532d">jeotermal, hidroelektrik) kullanılmalı.</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#14532d">• Doğal çevre korunarak ekonomik</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">kalkınma sürdürülebilir kılınmalıdır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
